// Writes app/common/themes/ikadocPalette.ts from palette.json.
// palette.json comes from extract.js, run in the IkaDoc frontend (see README.md).
// Development only; the generated file is committed.
//
//   node devtools/ikadoc-theme-tokens/generate.mjs

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const REPO = resolve(HERE, "../..");

const OUTPUT = join(REPO, "app/common/themes/ikadocPalette.ts");

const { extractedFrom, extractedAt, palette } = JSON.parse(
  readFileSync(join(HERE, "palette.json"), "utf8"),
);

const STYLES = ["owarelin", "material"];
const APPEARANCES = ["light", "dark"];

for (const style of STYLES) {
  for (const appearance of APPEARANCES) {
    if (!palette[style]?.[appearance]) {
      throw new Error(`palette.json has no ${style} ${appearance} palette`);
    }
  }
}

// Object literal in the project's style: unquoted keys, trailing commas.
const literal = (value, indent = "") => {
  if (typeof value === "string") {
    return JSON.stringify(value);
  }

  const inner = `${indent}  `;
  const entries = Object.entries(value)
    .map(([key, child]) => `${inner}${key}: ${literal(child, inner)},`)
    .join("\n");

  return `{\n${entries}\n${indent}}`;
};

const output = `// Generated by devtools/ikadoc-theme-tokens/generate.mjs — do not edit by hand.
// Colors resolved in the IkaDoc frontend (${extractedFrom}, ${extractedAt}).

export const IKADOC_PALETTE = ${literal(palette)} as const;

export type IkaDocVisualStyleName = keyof typeof IKADOC_PALETTE;

type PaletteGroups = typeof IKADOC_PALETTE.owarelin.light;

export type IkaDocPalette = {
  [Group in keyof PaletteGroups]: Record<keyof PaletteGroups[Group], string>;
};
`;

writeFileSync(OUTPUT, output);

console.log(`Wrote ${OUTPUT}`);
